fn clip(a: Vec<i8>, min: i8, max: i8) -> Vec<i8> {
    // Pre-allocate a vector of the same length for the result
    let mut result = Vec::with_capacity(a.len());

    for x in a {
        // First ensure x is at least `min`, then ensure it's at most `max`.
        let clipped = x.max(min).min(max);
        result.push(clipped);
    }

    result
}

